INSERT INTO `customer_product_translations` VALUES (1,1,'MI A1  Rose Gold','1','<p>NETWORK	Technology&nbsp;</p><ul><li><span style=\"font-family: &quot;Open Sans&quot;, sans-serif; font-size: 13px;\">GSM / HSPA / LTE</span></li></ul><p>BODY	</p><ul><li>Dimensions&nbsp;<span style=\"font-size: 1.125rem; font-family: &quot;Open Sans&quot;, sans-serif;\">155.4 x 75.8 x 7.3 mm (6.12 x 2.98 x 0.29 in)</span></li><li>Weight	165 g (5.82 oz)\r\n</li><li>Build	Glass front (Gorilla Glass 3), aluminum back, aluminum frame\r\n</li><li>SIM	Hybrid Dual SIM (Nano-SIM, dual stand-by)\r\n</li></ul><p>DISPLAY	</p><ul><li>Type	LTPS IPS LCD\r\n</li><li>Size	5.5 inches, 82.6 cm2 (~70.1% screen-to-body ratio)\r\n</li><li>Resolution	1080 x 1920 pixels, 16:9 ratio (~403 ppi density)\r\n</li><li>Protection	Corning Gorilla Glass 3\r\n</li></ul><p>PLATFORM	</p><ul><li>OS	Android 7.1.2 (Nougat), upgradable to Android 9.0 (Pie), Android One\r\n</li><li>Chipset	Qualcomm MSM8953 Snapdragon 625 (14 nm)\r\n</li><li>CPU	Octa-core 2.0 GHz Cortex-A53\r\n</li><li>GPU	Adreno 506\r\n</li></ul><p>MEMORY	</p><ul><li>Card slot	microSDXC (uses shared SIM slot)\r\n</li><li>Internal	64GB 4GB RAM<span style=\"font-size: 1.125rem; font-family: &quot;Open Sans&quot;, sans-serif;\">&nbsp;eMMC 5.1</span></li></ul><p>MAIN CAMERA	</p><ul><li>Dual	12 MP, f/2.2, 26mm (wide), 1/2.9\", 1.25µm, PDAF&nbsp;<span style=\"font-size: 1.125rem; font-family: &quot;Open Sans&quot;, sans-serif;\">12 MP, f/2.6, 50mm (telephoto), 1.0µm, AF, 2x optical zoom</span></li><li>Features	Dual-LED dual-tone flash, HDR, panorama\r\n</li><li>Video	4K@30fps, 1080p@30fps, 720p@120fps\r\n</li><li>SELFIE CAMERA	Single	5 MP\r\n</li><li>Video	1080p@30fps\r\n</li></ul><p>SOUND	</p><ul><li>Loudspeaker	Yes\r\n</li><li>3.5mm jack	Yes\r\n</li></ul><p>COMMS	</p><ul><li>WLAN	Wi-Fi 802.11 a/b/g/n/ac, dual-band, Wi-Fi Direct, hotspot\r\n</li><li>Bluetooth	4.2, A2DP, LE\r\n</li><li>GPS	Yes, with A-GPS, GLONASS, BDS\r\n</li><li>NFC	No\r\n</li><li>Infrared port	Yes\r\n</li><li>Radio	FM radio\r\n</li><li>USB	USB Type-C 2.0\r\n</li></ul><p>FEATURES	</p><ul><li>Sensors	Fingerprint (rear-mounted), accelerometer, gyro, proximity\r\n</li><li>BATTERY	Type	Li-Po 3080 mAh, non-removable\r\n</li><li>Charging	Charging 10W</li></ul>','en','2021-08-28 11:10:28','2021-08-28 11:10:28'),(2,2,'Used Huawei Nova 3i on sale','pc','<p><ul><li>Dual Sim, 3G, 4G, VoLTE, Wi-Fi\r\n</li></ul><ul><li>Kirin 710, Octa Core, 2.2 GHz Processor\r\n</li></ul><ul><li>4 GB RAM, 128 GB inbuilt\r\n</li></ul><ul><li>3340 mAh Battery\r\n</li></ul><ul><li>6.3 inches, 1080 x 2340 px Display\r\n</li></ul><ul><li>16 MP + 2 MP Dual Rear &amp; 24 MP + 2 MP Dual Front Camera\r\n</li></ul><ul><li>Memory Card (Hybrid), upto 256 GB\r\n</li></ul><ul><li>Android v9&nbsp;</li></ul></p>','en','2021-09-13 15:59:21','2021-09-13 16:10:36'),(3,3,'Jelani Hammond',NULL,'Vero ut eum sit, adi.asdsad asdasdsd','en','2026-07-17 09:07:19','2026-07-17 09:07:19'),(4,4,'Christopher Horne',NULL,'Maxime et natus temp.asdasdasd','en','2026-07-17 10:12:37','2026-07-17 10:12:37'),(5,5,'Stewart Howard',NULL,NULL,'en','2026-07-17 10:36:05','2026-07-17 10:36:05'),(6,6,'Stewart Howard',NULL,NULL,'en','2026-07-17 10:36:23','2026-07-17 10:36:23'),(7,7,'Autel Robotics EVO II 8K Drone Rugged Bundle','pc','<p>•	Carrying Case, Extra Battery &amp; Propellers\r\n</p><p>•	Capture 8K Video &amp; 48MP Photos\r\n</p><p>•	12-Sensor Obstacle Avoidance\r\n</p><p>•	Up to 40-Minute Flight Time\r\n</p><p>•	HD Transmission up to 5.6 Miles\r\n</p><p>•	Includes Remote with 3.3\" OLED Display\r\n</p><p>•	Record HDR Video at up to 4K Resolution\r\n</p><p>•	120 fps Slo-Mo at up to 2K Resolution\r\n</p><p>•	4x In-Camera Lossless Zoom\r\n</p><p>•	Foldable Design for Easier Portability\r\n</p><p><br></p>','en','2026-07-18 07:18:15','2026-07-18 07:18:15'),(8,8,'Autel Robotics EVO II PRO 6K Drone Rugged Bundle','pc','<p>•	Capture 6K Video &amp; 20MP Photos\r\n</p><p>•	Variable Aperture from f/2.8 to f/11\r\n</p><p>•	1\" Senso