  `seller_id` int DEFAULT NULL,
  `assign_delivery_boy` int DEFAULT NULL,
  `delivery_status` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `payment_status_viewed` int DEFAULT '1',
  `commission_calculated` int NOT NULL DEFAULT '0',
  `delivery_history_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `billing_address` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `gift_amount` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `gift_to` int DEFAULT '0',
